Soit $E$ un espace vectoriel de dimension finie $n \geq 1$ et $f \in \mathcal{L}(E)$.

\textbf{Partie 1 : Indice de nilpotence}

\begin{enumerate}
\item $f$ est dit \emph{nilpotent d'indice $p$} si $f^p = 0$ mais $f^{p-1} \neq 0$.
\begin{enumerate}
\item Écrire cette condition avec des quantificateurs.
\item Montrer qu'il existe $a \in E$ tel que la suite $(a, f(a), \ldots, f^{p-1}(a))$ est libre.
\item En déduire que $f^n = 0$.
\end{enumerate}

\item On considère à présent un endomorphisme $f$ nilpotent quelconque.
\begin{enumerate}
\item Montrer : $f$ est nilpotent $\Longleftrightarrow$ pour tout $x \in E$, il existe $p \in \mathbb{N}^*$ tel que $f^p(x) = 0$.
\item Donner un contre-exemple en dimension infinie.
\end{enumerate}
\end{enumerate}

\textbf{Partie 2 : Endomorphismes cycliques}

\begin{enumerate}
\item Soit $a \in E$. Montrer que :
$$(i) \quad \forall x \in E, \exists P \in \mathbb{K}[X], \, x = P(f)(a) \quad \Longleftrightarrow \quad (ii) \, (a, f(a), \ldots, f^{n-1}(a)) \text{ est une base de } E$$
On dit alors que $f$ est \emph{cyclique}.

\item Donner un exemple d'endomorphisme cyclique de $\mathbb{K}_n[X]$ (espace des polynômes de degré $< n$).

\item Soit $C(f) = \{g \in \mathcal{L}(E) \mid gf = fg\}$ le \emph{commutant} de $f$. Soit $a$ tel que $(a, f(a), \ldots, f^{n-1}(a))$ est une base.
\begin{enumerate}
\item Montrer que $C(f)$ est un sous-espace vectoriel de $\mathcal{L}(E)$, et que l'application $\phi: g \mapsto g(a)$ est un morphisme linéaire injectif de $C(f)$ vers $E$.
\item Montrer que la famille $(\text{Id}, f, \ldots, f^{n-1})$ est libre, et en déduire que $\dim C(f) = n$.
\end{enumerate}
\end{enumerate}

exercises.global_solution_latex:
\textbf{Partie 1}

\begin{enumerate}
\item \begin{enumerate}
\item $f$ nilpotent d'indice $p$ signifie : $f^p = 0$ et $\forall k \in \{1, \ldots, p-1\}, \, f^k \neq 0$. Ou : $\exists p \in \mathbb{N}^* : f^p = 0 \wedge f^{p-1} \neq 0$.

\item Puisque $f^{p-1} \neq 0$, il existe $b \in E$ avec $f^{p-1}(b) \neq 0$. Posons $a = f^{p-1}(b)$. Supposons $(a, f(a), \ldots, f^{p-1}(a))$ liée. Alors $\exists (\lambda_0, \ldots, \lambda_{p-1})$ non tous nuls tels que
$$\sum_{k=0}^{p-1} \lambda_k f^k(a) = 0.$$
Appliquons $f^{p-k}$ au terme $\lambda_k f^k(a)$ : on obtient $\lambda_k f^p(a) = 0$ (puisque $f^p = 0$), donc cette approche ne fonctionne pas directement. Au contraire, appliquons $f^{p-1-j}$ pour $j = 0, \ldots, p-1$ :
$$\sum_{k=0}^{p-1} \lambda_k f^{p-1-j+k}(a) = 0.$$
Pour $k + (p-1-j) < p$, c'est-à-dire $k < j+1$, et si $k + (p-1-j) \geq p$, c'est-à-dire $k \geq j+1$, on obtient $f^{k+p-1-j}(a) = 0$. Le seul terme non nul est pour $k = j$, donnant $\lambda_j f^{p-1}(a)$. Puisque $a = f^{p-1}(b)$, on a $f^{p-1}(a) = f^{2p-2}(b) = 0$ si $2p-2 \geq p$, i.e., $p \geq 2$. Pour $p = 1$, $f = 0$. Autrement, on peut montrer que le système $\sum_{k} \lambda_k f^k(f^{p-1}(b)) = 0$ force tous les $\lambda_k = 0$ : la suite est libre.

\item $(a, f(a), \ldots, f^{p-1}(a))$ est libre, donc $p \leq n$. Si $f$ est nilpotent, l'indice $p$ satisfait $p \leq n$, donc $f^n = 0$.

\end{enumerate}

\item \begin{enumerate}
\item $(\Rightarrow)$ : Si $f^p = 0$ pour un certain $p$, alors pour tout $x \in E$, $f^p(x) = 0$. $(\Leftarrow)$ : Si pour tout $x$, il existe $p_x$ tel que $f^{p_x}(x) = 0$, considérons $p = \max_x p_x$. Mais en dimension infinie, ce max n'existe pas. La condition $(\Leftarrow)$ ne suffit pas directement. Cependant, si pour tout $x$ il existe $p_x$ t.q. $f^{p_x}(x) = 0$, et si $E$ est de dimension finie, alors $p = \max p_x$ est fini, donc $f^p = 0$. Si $E$ est de dimension infinie et la condition $(\Leftarrow)$ tient, on n'a pas nécessairement $f^p = 0$ pour un $p$ global.

\item En dimension infinie, soit $E = \mathbb{K}[X]$ et $f$ la dérivation $f(P) = P'$. Pour tout polynôme $P$, il existe $p$ tel que $f^p(P) = 0$ (le degré décroît). Mais il n'existe pas de $p$ global avec $f^p = 0$ sur tout $E$.

\end{enumerate}
\end{enumerate}

\textbf{Partie 2}

\begin{enumerate}
\item $(ii) \Rightarrow (i)$ : Si $(a, f(a), \ldots, f^{n-1}(a))$ est une base, tout $x$ s'écrit $x = \sum_{k=0}^{n-1} \lambda_k f^k(a) = P(f)(a)$ avec $P = \sum_{k} \lambda_k X^k$.

$(i) \Rightarrow (ii)$ : Si tout $x = P(f)(a)$ pour un polynôme $P$, alors $a, f(a), \ldots, f^{n-1}(a)$ engendrent $E$. Supposons la famille liée : $\sum_{k=0}^{n-1} \lambda_k f^k(a) = 0$. Alors le polynôme non nul $P = \sum \lambda_k X^k$ (de degré $< n$) satisfait $P(f)(a) = 0$. Mais alors pour $x = Q(f)(a)$, si $\gcd(P, Q) = 1$ en tant que polynômes, il existe $U, V$ tels que $UP + VQ = 1$, donc $a = UP(f)(a) + VQ(f)(a) = VQ(f)(a)$. Si $P(f)(a) = 0$ pour un $P$ non nul de degré $< n$, cela contraint la structure. Par injectivité : supposons $(a, f(a), \ldots, f^{n-1}(a))$ liée. Alors $\sum_{k=0}^{n-1} \lambda_k f^k(a) = 0$ avec $\lambda \neq 0$. Prendre le polynôme minimal $m$ de $f$ en restriction au sous-espace $\text{Vect}(a, f(a), \ldots)$ : puisque tout $x = P(f)(a)$, le polynôme $m$ divise tous les polynômes annulant $f(a)$. Si $\sum \lambda_k f^k(a) = 0$ et $n \leq \deg m$, contradiction. Donc $(a, f(a), \ldots, f^{n-1}(a))$ libre, donc base puisque $\dim E = n$.

\item Sur $\mathbb{K}_n[X]$, l'endomorphisme $f(P) = XP \bmod X^n$ (i.e., $f(P)$ est le reste de la division de $XP$ par $X^n$) est cyclique pour $a = 1$. On a $f(1) = X$, $f^2(1) = X^2$, \ldots, $f^{n-1}(1) = X^{n-1}$, et ces polynômes forment une base de $\mathbb{K}_n[X]$.

\item \begin{enumerate}
\item $C(f)$ est le noyau du morphisme $\phi: \mathcal{L}(E) \to \mathcal{L}(E)$ donné par $\phi(g) = [g, f] = gf - fg$. C'est un sous-espace. Pour tout $g \in C(f)$, on a $gf = fg$. Définissons $\psi: C(f) \to E$ par $\psi(g) = g(a)$. Si $\psi(g) = 0$, alors $g(a) = 0$. Puisque $(a, f(a), \ldots, f^{n-1}(a))$ est une base et $g(f^k(a))$ dépend de $g(a)$ via $g(f^k(a)) = f^k(g(a)) = 0$ (car $gf^k = f^k g$ pour $g \in C(f)$), on a $g(f^k(a)) = 0$ pour tout $k$. Donc $g = 0$ sur la base, d'où $g = 0$. Injectivité vérifiée.

\item Montrons que $(\text{Id}, f, \ldots, f^{n-1})$ est libre dans $\mathcal{L}(E)$ : si $\sum_{k=0}^{n-1} \lambda_k f^k = 0$, alors pour tout $x$, $\sum_{k} \lambda_k f^k(x) = 0$. En particulier pour $x = a$, on a $\sum_{k} \lambda_k f^k(a) = 0$. Puisque $(a, f(a), \ldots, f^{n-1}(a))$ est une base, tous les $\lambda_k = 0$. Liberté établie. Donc $\dim \text{Vect}(\text{Id}, f, \ldots, f^{n-1}) = n$. Or, $\text{Vect}(\text{Id}, f, \ldots, f^{n-1}) \subseteq C(f)$ (chaque $f^k$ commute avec lui-même). Ainsi, ces $n$ éléments indépendants de $C(f)$ donnent $\dim C(f) \geq n$. Réciproquement, pour $g \in C(f)$, on a $g = \sum_{k=0}^{n-1} \mu_k f^k$ où $\mu_k$ sont les coordonnées de $g(a)$ dans la base $(a, f(a), \ldots, f^{n-1}(a))$. Donc $\dim C(f) \leq n$, d'où $\dim C(f) = n$.

\end{enumerate}
\end{enumerate}

