\begin{enumerate}
\item \begin{enumerate}
\item Calculer le rang de la matrice $\displaystyle A = \begin{pmatrix} 2 & 1 & 3 \\ -1 & 2 & 1 \\ 1 & 1 & 2 \end{pmatrix}$ sur les entiers.

\item Calculer le rang de la matrice $\displaystyle B = \begin{pmatrix} -1 & 0 & 1 & 0 \\ 2 & 5 & -2 & -5 \\ 6 & 5 & 4 & 3 \\ 9 & 5 & 0 & 1 \\ 7 & 0 & 5 & -3 \end{pmatrix}$ (matrice $5 \times 4$).
\end{enumerate}

\item \begin{enumerate}
\item Calculer le rang de la matrice $\displaystyle M(a) = \begin{pmatrix} a & 1 & 1 \\ 1 & a & 1 \\ 1 & 1 & a \end{pmatrix}$ en fonction du paramètre $a \in \mathbb{K}$.

\item Calculer le rang de la matrice de Vandermonde 
$$V = \begin{pmatrix} 1 & 1 & 1 \\ a & b & c \\ a^2 & b^2 & c^2 \end{pmatrix}$$
en fonction des paramètres $a, b, c \in \mathbb{K}$.
\end{enumerate}

Soit $A, B \in \mathcal{M}_n(\mathbb{K})$ et la matrice bloc 
$$M = \begin{pmatrix} A & A \\ A & A + B \end{pmatrix} \in \mathcal{M}_{2n}(\mathbb{K}).$$

\begin{enumerate}
\item Calculer $M^2$.
\item Déterminer une condition nécessaire et suffisante pour que $M$ soit inversible, et exprimer $M^{-1}$ en fonction de $A$ et $B$.
\end{enumerate}
